import {
  PlaneGeometry,
  MeshBasicNodeMaterial,
  texture as textureNode,
  uniform,
  float,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const { scenePosition } = config;
  const texture = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');

  // Use a plane size matching the source aspect ratio 512:320 = 1.6
  // Choose a reasonable size in scene units: width 2, height 1.25
  const width = 2.0;
  const height = 1.25;
  const geometry = new PlaneGeometry(width, height);

  // Create a node material using the texture node
  const material = new MeshBasicNodeMaterial();
  material.colorNode = textureNode(texture);

  // Support color-space and mapping (assume sRGB)
  texture.colorSpace = 'srgb';

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(
    scenePosition.x,
    scenePosition.y,
    scenePosition.z
  );
  mesh.rotation.set(
    scenePosition.rotationX || 0,
    scenePosition.rotationY || 0,
    scenePosition.rotationZ || 0
  );
  mesh.scale.set(
    scenePosition.scaleX || 1,
    scenePosition.scaleY || 1,
    scenePosition.scaleZ || 1
  );

  // Attach empty handlers (no interactive behaviors for this node)
  mesh.userData.handlers = {};

  // Cleanup: dispose geometry, material, texture
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // No GSAP timelines to kill for this static node
  };

  return mesh;
}
